 equip=["Uzun to‘g‘ri o‘tkazgich va aylanma halqa (N o‘ramli) maketlari", "Teslametr (Xoll datchigi) yoki smartfondagi magnitometr (Phyphox ilovasi)", "Tok manbai (0–5 A), ampermetr", "Millimetrli chizg‘ich, datchikni siljituvchi taglik"],
 theory=[
  ("Bio–Savar–Laplas qonuni", r"<p>Tok elementi \(Id\vec l\) hosil qiladigan maydon: \(d\vec B=\dfrac{\mu_0}{4\pi}\dfrac{I\,d\vec l\times\vec r}{r^3}\), \(\mu_0=4\pi\cdot10^{-7}\) Gn/m. Integrallash quyidagi natijalarni beradi.</p>"),
  ("Uzun to‘g‘ri o‘tkazgich", r"$$B=\frac{\mu_0I}{2\pi r}.$$<p>Kuch chiziqlari o‘tkazgichni o‘rab olgan aylanalar, yo‘nalishi parma qoidasi bilan topiladi. \(B\cdot r=\text{const}\) — tajribani tekshirishning qulay usuli.</p>"),
  ("Aylanma halqa o‘qida", r"$$B(x)=\frac{\mu_0NIR^2}{2\left(R^2+x^2\right)^{3/2}},\qquad B(0)=\frac{\mu_0NI}{2R}.$$<p>Uzoq masofada (\(x\gg R\)) maydon \(x^{-3}\) kabi kamayadi — halqa magnit dipoli kabi bo‘ladi.</p>"),
  ("Yer maydonini hisobga olish", r"<p>Datchik Yer maydonini (≈ 50 mkTl) ham sezadi. Har bir nuqtada tok bilan va toksiz o‘lchab, ayirmasini olish yoki tok yo‘nalishini almashtirib, \(B=(B_+-B_-)/2\) dan foydalanish kerak.</p>")],
 proc=["Teslametrni toksiz holda nolga keltiring (yoki fon qiymatini yozing).", r"To‘g‘ri o‘tkazgichdan \(I=5\) A o‘tkazib, \(r=1\ldots6\) sm masofalarda \(B\) ni o‘lchang.", "Tok yo‘nalishini almashtirib takrorlang, o‘rtachani oling.", r"\(B(1/r)\) grafigini quring; qiyalikdan \(\mu_0\) ni baholang.", r"Halqa markazidan o‘q bo‘ylab \(x=0\ldots10\) sm da \(B\) ni o‘lchang.", "Natijalarni nazariy egri chiziq bilan bitta grafikda solishtiring."],
