  (r"Halqa markazidagi induksiya formulasi:", [r"\(\mu_0NI/2R\)", r"\(\mu_0NI/2\pi R\)", r"\(\mu_0NI/R^2\)", r"\(\mu_0I/4\pi R\)"], 0, "Bio–Savar–Laplas natijasi."),
  (r"Halqa o‘qida \(x\gg R\) da maydon:", [r"\(x^{-3}\) kabi kamayadi", r"\(x^{-1}\) kabi kamayadi", "o‘zgarmaydi", r"\(x^{-2}\) kabi kamayadi"], 0, "Magnit dipol maydoni."),
