  (r"To‘g‘ri tok maydoni yo‘nalishi qaysi qoida bilan topiladi?", ["parma (o‘ng vint) qoidasi", "chap qo‘l qoidasi", "Lens qoidasi", "Kirxgoff qoidasi"], 0, "Maktab kursidagi qoida."),
  (r"Yer maydoni ta’sirini chiqarib tashlashning eng oddiy usuli:", ["tok yo‘nalishini almashtirib, ayirmaning yarmini olish", "tokni oshirish", "datchikni uzoqlashtirish", "o‘lchashni kechqurun o‘tkazish"], 0, r"\(B=(B_+-B_-)/2\)."),
